const item = $input.first();
const binaryKeys = Object.keys(item.binary ?? {});
const binaryProperty = binaryKeys.includes('data') ? 'data' : binaryKeys[0];
if (!binaryProperty) {
  throw new Error('Desired blocklist file does not contain binary data');
}
const raw = (await this.helpers.getBinaryDataBuffer(0, binaryProperty)).toString('utf8');
if (!raw.length) {
  throw new Error('Desired blocklist file is empty');
}
const desiredMap = new Map();
for (const rawLine of String(raw).split(/\r?\n/)) {
  const line = String(rawLine).trim();
  if (!line) continue;
  const match = line.match(/^([a-f0-9]{64})\s+(SHA256_[A-Z0-9_]+)$/i);
  if (!match) continue;
  desiredMap.set(match[1].toLowerCase(), match[2].toUpperCase());
}
const desiredHashes = [...desiredMap.keys()].sort();
const desiredLines = desiredHashes.map((hash) => `${hash} ${desiredMap.get(hash)}`);
return {
  json: {
    desired_raw: raw,
    desired_lines: desiredLines,
    desired_hashes: desiredHashes,
    desired_map: Object.fromEntries(desiredMap),
    desired_count: desiredHashes.length
  }
};

const item = $input.first();
const binaryKeys = Object.keys(item.binary ?? {});
const binaryProperty = binaryKeys.includes('data') ? 'data' : binaryKeys[0];
if (!binaryProperty) {
  return { json: { known_present_raw: '', known_present_hashes: [], known_present_count: 0 } };
}
const raw = (await this.helpers.getBinaryDataBuffer(0, binaryProperty)).toString('utf8');
if (!raw.length) {
  return { json: { known_present_raw: '', known_present_hashes: [], known_present_count: 0 } };
}
const hashes = String(raw)
  .split(/\r?\n/)
  .map((line) => String(line).trim().toLowerCase())
  .filter(Boolean)
  .filter((line) => /^[a-f0-9]{64}$/i.test(line));
const uniqueHashes = [...new Set(hashes)].sort();
return {
  json: {
    known_present_raw: raw,
    known_present_hashes: uniqueHashes,
    known_present_count: uniqueHashes.length
  }
};

const desiredMap = $json.desired_map && typeof $json.desired_map === 'object' ? $json.desired_map : {};
const desiredHashes = Array.isArray($json.desired_hashes) ? $json.desired_hashes.map((hash) => String(hash).trim().toLowerCase()).filter(Boolean) : [];
const knownHashes = Array.isArray($json.known_present_hashes) ? $json.known_present_hashes.map((hash) => String(hash).trim().toLowerCase()).filter(Boolean) : [];
const desiredSet = new Set(desiredHashes);
const knownSet = new Set(knownHashes);
const deltaHashes = [...desiredSet].filter((hash) => !knownSet.has(hash));
const chunkSize = Math.max(1, Number($env.SOC_BITDEFENDER_ADD_CHUNK_SIZE || '100'));
const chunkHashes = deltaHashes.slice(0, chunkSize);
const chunkLines = chunkHashes.map((hash) => `${hash} ${String(desiredMap[hash] || 'SHA256_UNKNOWN').toUpperCase()}`);
return [{
  json: {
    desired_lines: [...desiredSet].map((hash) => `${hash} ${String(desiredMap[hash] || 'SHA256_UNKNOWN').toUpperCase()}`),
    desired_hashes: [...desiredSet].sort(),
    desired_count: desiredSet.size,
    desired_map: desiredMap,
    known_present_hashes: [...knownSet].sort(),
    known_present_count: knownSet.size,
    delta_total_count: deltaHashes.length,
    chunk_hashes: chunkHashes,
    chunk_lines: chunkLines,
    chunk_count: chunkHashes.length,
    chunk_size: chunkSize,
    sync_started_at: new Date().toISOString()
  }
}];

const apiKey = String($env.SOC_BITDEFENDER_API_KEY || '').trim();
const companyId = String($env.SOC_BITDEFENDER_COMPANY_ID || '').trim();
const incidentsUrl = String($env.SOC_BITDEFENDER_INCIDENTS_V12_URL || '').trim();
const chunkLines = Array.isArray($json.chunk_lines) ? $json.chunk_lines : [];
if (!apiKey || !companyId || !incidentsUrl) {
  throw new Error('Missing Bitdefender environment configuration');
}
if (!chunkLines.length) {
  return [{ json: { ...$json, add_request_id: '', add_result: 'noop', added_lines: [], added_hashes: [], added_count: 0, sync_completed_at: new Date().toISOString() } }];
}
const auth = Buffer.from(`${apiKey}:`).toString('base64');
const rules = chunkLines.map((line) => {
  const match = String(line).match(/^([a-f0-9]{64})\s+(SHA256_[A-Z0-9_]+)$/i);
  if (!match) {
    throw new Error(`Invalid line for Bitdefender sync: ${line}`);
  }
  const hash = match[1].toLowerCase();
  const tag = match[2].toUpperCase();
  return {
    note: `SOC|source=hash_sha256.txt|tag=${tag}`,
    details: {
      algorithm: 'sha256',
      hash
    }
  };
});
const requestId = `soc-bitdefender-incremental-${Date.now()}`;
const response = await this.helpers.httpRequest({
  method: 'POST',
  url: incidentsUrl,
  headers: {
    Authorization: `Basic ${auth}`,
    'Content-Type': 'application/json',
    Accept: 'application/json'
  },
  body: {
    jsonrpc: '2.0',
    method: 'addToBlocklist',
    params: {
      companyId,
      type: 'hash',
      rules,
      recursive: false
    },
    id: requestId
  },
  json: true
});
if (response?.error) {
  throw new Error(`Bitdefender addToBlocklist error ${response.error.code}: ${response.error.message}`);
}
if (response?.result !== true) {
  throw new Error(`Bitdefender addToBlocklist returned unexpected result: ${JSON.stringify(response)}`);
}
const addedHashes = rules.map((rule) => String(rule.details.hash).toLowerCase());
return [{
  json: {
    ...$json,
    add_request_id: requestId,
    add_result: 'success',
    added_lines: chunkLines,
    added_hashes: addedHashes,
    added_count: chunkLines.length,
    sync_completed_at: new Date().toISOString()
  }
}];

const knownHashes = Array.isArray($json.known_present_hashes) ? $json.known_present_hashes : [];
const addedHashes = Array.isArray($json.added_hashes) ? $json.added_hashes : [];
const merged = [...new Set([...knownHashes, ...addedHashes].map((hash) => String(hash).trim().toLowerCase()).filter(Boolean))].sort();
return {
  json: {
    ...$json,
    known_present_hashes: merged,
    known_present_text: merged.length ? `${merged.join('\n')}\n` : '',
    known_present_count_after: merged.length
  }
};

const knownBefore = Number($json.known_present_count || 0);
const knownAfter = Number($json.known_present_count_after || knownBefore);
const addedCount = Number($json.added_count || 0);
const status = addedCount > 0 ? 'applied' : 'noop';
return {
  json: {
    status_json: JSON.stringify({
      scope: 'incremental',
      status,
      sync_started_at: $json.sync_started_at,
      sync_completed_at: $json.sync_completed_at || new Date().toISOString(),
      desired_count: Number($json.desired_count || 0),
      known_present_count_before: knownBefore,
      known_present_count_after: knownAfter,
      delta_total_count: Number($json.delta_total_count || 0),
      added_count: addedCount,
      add_request_id: $json.add_request_id || ''
    }, null, 2)
  }
};
